'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t;
let variant=OrionProgress.variant('signal'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget;
let stage=0,bits=[],solved=false,hintDepth=0,state='ready',tested=false,saveFailed=false;
function source(v=variant,s=stage){const n=[3,5,6,7,9,10,11,13][v],data=Array.from({length:4},(_,i)=>(n>>(3-i))&1);if(s===2)data.reverse();return [...data,data.reduce((a,b)=>a+b,0)%2];}
function flips(){return bits.filter((b,i)=>b!==source()[i]).length;}
function alarm(){return bits.reduce((a,b)=>a+b,0)%2===1;}
function resetTrial(){bits=source();if(stage===0)bits[4]=1-bits[4];solved=false;hintDepth=0;state='ready';tested=false;saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('signal')){variant=v;stage=0;resetTrial();}
function toggle(i){if(solved||!Number.isInteger(i)||i<0||i>4||stage===0&&i!==4)return;bits[i]^=1;tested=false;state='ready';render();}
function succeed(){solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('starspeech');render();if(stage<2)$('next').focus();}
function check(){if(solved)return;if(stage===0){if(alarm()){state='wrong';render();}else succeed();return;}if(flips()!==stage){state='count';tested=false;render();return;}tested=true;state='tested';render();}
function answer(value){if(!tested||solved||typeof value!=='boolean')return;if(value!==alarm()){state='wrongAnswer';render();return;}succeed();}
function hints(){return [t('Count the lamps showing 1. Compare your row with the original.','數數顯示 1 的燈，並比較目前與原始燈號。'),t('The sender makes an even total: 0, 2 or 4. One changed lamp switches even to odd. Two changes switch it back to even.','發送時總數是偶數：0、2 或 4。一盞改變會把偶數變成奇數；兩盞改變則會回到偶數。'),stage===0?t(`Set the gold checking lamp to ${source()[4]}.`,`把金色檢查燈設成 ${source()[4]}。`):t(`Restore, change ${stage} different lamp${stage===1?'':'s'}, then test. The detector will show ${stage===1?'an alarm':'no alarm'}.`,`還原後改變 ${stage} 盞不同的燈，再測試。偵測器會顯示${stage===1?'警報':'沒有警報'}。`)];}
function render(){const complete=solved&&stage===2,count=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Broken Star Signal · Orion','被干擾的星空訊號 · Orion');$('stageTitle').textContent=t(`Signal ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 個訊號 · 第 ${variant+1} 組`);$('sceneStatus').textContent=t(`Signal seals restored · ${count} / 3`,`已修復 ${count} / 3 道訊號封印`);$('seals').textContent=Array.from({length:3},(_,i)=>i<count?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);
$('instruction').textContent=stage===0?t('Set the gold checking lamp so the total number of lit lamps is even (0, 2 or 4).','設定金色檢查燈，令亮燈總數是偶數（0、2 或 4）。'):t(`Change exactly ${stage} different lamp${stage===1?'':'s'}, then test the detector.`,`改變剛好 ${stage} 盞不同的燈，再測試偵測器。`);
$('original').hidden=stage===0;$('original').textContent=t('Original sent row: ','原始發送燈號：')+source().join('  ');
for(let i=0;i<5;i++){const el=$('bit'+i),name=i===4?t('Check','檢查'):t(`Lamp ${i+1}`,`燈 ${i+1}`);el.disabled=solved||stage===0&&i!==4;el.setAttribute('aria-pressed',String(!!bits[i]));el.setAttribute('aria-label',`${name}: ${bits[i]} · ${bits[i]?t('on','亮'):t('off','熄')}`);el.innerHTML=`<span class="bulb" aria-hidden="true"></span><span>${name}<br>${bits[i]} · ${bits[i]?t('on','亮'):t('off','熄')}</span>`;}
$('count').textContent=t(`Lit lamps: ${bits.reduce((a,b)=>a+b,0)}`,`亮燈數：${bits.reduce((a,b)=>a+b,0)}`)+(stage? t(` · Changed: ${flips()} / ${stage}`,` · 已改變：${flips()} / ${stage}`):'');
$('goal').textContent=[t('Prepare a message with an even total.','準備一個亮燈總數為偶數的訊息。'),t('Investigate one changed bit.','調查一個位元改變的情況。'),t('Investigate two changed bits.','調查兩個位元改變的情況。')][stage];
$('reading').textContent=stage===0?t('The checking lamp is extra information beside the four message lamps.','四盞訊息燈旁的檢查燈，提供額外資料。'):tested?(alarm()?t('⚠ ALARM · Odd total detected','⚠ 警報 · 偵測到奇數'):t('✓ NO ALARM · Even total detected','✓ 沒有警報 · 偵測到偶數')):t('Detector waiting · Test your changed signal.','偵測器等待中 · 測試改變後的訊號。');
const msg={ready:t('Try the lamps. You can restore and experiment as often as you like.','試試燈號。你可以隨時還原，再做實驗。'),wrong:t('The total is still odd. Try the checking lamp again.','總數仍是奇數。再試試檢查燈。'),count:t(`Change exactly ${stage} different lamps before testing.`,`測試前，請改變剛好 ${stage} 盞不同的燈。`),tested:t('Read the detector, then record what it showed below.','閱讀偵測器，再在下面記錄它顯示了甚麼。'),wrongAnswer:t('Look at the detector’s message and try again.','看看偵測器的訊息，再試一次。'),success:stage===2?t('Two bits changed, but no alarm! A passed check does not prove the message is unchanged.','兩個位元變了，卻沒有警報！通過檢查不代表訊息沒有改變。'):t('Discovery recorded. A signal seal opens!','發現已記錄。一道訊號封印打開了！')};$('feedback').textContent=msg[state];
$('answers').hidden=!tested||solved;for(const id of ['check','retry'])$(id).hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved||hintDepth===3;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintDepth>0));$('hints').hidden=!hintDepth;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('');$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('starspeech')?t('Star Speech Sigil saved in your collection.','星語符印已存入收藏。'):'';
}
for(let i=0;i<5;i++)$('bit'+i).onclick=()=>toggle(i);$('check').onclick=check;$('alarm').onclick=()=>answer(true);$('quiet').onclick=()=>answer(false);$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();$('bit0').focus();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);render();};$('replay').onclick=()=>{const v=OrionProgress.nextVariant('signal',variant);observedVariant=OrionProgress.variant('signal');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('starspeech');render();};
function syncProgress(){const v=OrionProgress.variant('signal'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('starspeech')&&!saveFailed)resetMission();else render();}
window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
